/** Request leave (routes to my supervisor) — POST /api/v1/self/leave-requests (who may call: holders of self.leave.request). */
export function requestLeave(body: LeaveIn): Promise<LeaveRequestOut> {
  return api<LeaveRequestOut>("POST", `/self/leave-requests`, body, { idempotent: true });
}

/** My leave requests — GET /api/v1/self/leave-requests (who may call: holders of self.leave.request). */
export function myLeave(): Promise<LeaveRequestOut[]> {
  return api<LeaveRequestOut[]>("GET", `/self/leave-requests`, undefined);
}

/** Withdraw my pending request — POST /api/v1/self/leave-requests/{leave_request_id}/cancel (who may call: holders of self.leave.request). */
export function cancelLeave(leave_request_id: number): Promise<LeaveRequestOut> {
  return api<LeaveRequestOut>("POST", `/self/leave-requests/${leave_request_id}/cancel`, undefined);
}

/** My leave balances — GET /api/v1/self/leave-balances (who may call: holders of self.profile.view). */
export function myBalances(query?: { year?: number | null }): Promise<LeaveBalanceOut[]> {
  return api<LeaveBalanceOut[]>("GET", withQuery(`/self/leave-balances`, query), undefined);
}

/** My employee profile, payslips and attendance — GET /api/v1/self/profile (who may call: holders of self.profile.view). */
export function myProfile(): Promise<SelfProfileOut> {
  return api<SelfProfileOut>("GET", `/self/profile`, undefined);
}

/** One of my payslips — GET /api/v1/self/payslips/{payroll_item_id} (who may call: holders of self.profile.view). */
export function myPayslip(payroll_item_id: number): Promise<PayslipOut> {
  return api<PayslipOut>("GET", `/self/payslips/${payroll_item_id}`, undefined);
}

/** My duties (two weeks from today by default) — GET /api/v1/self/roster (who may call: holders of self.profile.view). */
export function myDuties(query?: { date_from?: string | null; date_to?: string | null }): Promise<RosterEntryOut[]> {
  return api<RosterEntryOut[]>("GET", withQuery(`/self/roster`, query), undefined);
}

/** Public holidays of a year (or a date range) — GET /api/v1/holidays (who may call: any logged-in user). */
export function listHolidays(query?: { year?: number | null; date_from?: string | null; date_to?: string | null; include_inactive?: boolean }): Promise<HolidayOut[]> {
  return api<HolidayOut[]>("GET", withQuery(`/holidays`, query), undefined);
}

/** Colleagues who could work one of my duties — GET /api/v1/self/roster/swap-options (who may call: holders of self.roster.swap). */
export function swapOptions(query: { roster_id: number }): Promise<SwapOptionsOut> {
  return api<SwapOptionsOut>("GET", withQuery(`/self/roster/swap-options`, query), undefined);
}

/** Ask a colleague to work one of my duties (cover or swap) — POST /api/v1/self/roster/swaps (who may call: holders of self.roster.swap). */
export function requestSwap(body: SwapIn): Promise<DutySwapOut> {
  return api<DutySwapOut>("POST", `/self/roster/swaps`, body, { idempotent: true });
}

/** Swap requests I made or was asked (open first) — GET /api/v1/self/roster/swaps (who may call: holders of self.roster.swap). */
export function mySwaps(): Promise<MyDutySwapOut[]> {
  return api<MyDutySwapOut[]>("GET", `/self/roster/swaps`, undefined);
}

/** Agree to work a colleague's duty — POST /api/v1/self/roster/swaps/{swap_id}/accept (who may call: holders of self.roster.swap). */
export function acceptSwap(swap_id: number, body: SwapNoteIn): Promise<DutySwapOut> {
  return api<DutySwapOut>("POST", `/self/roster/swaps/${swap_id}/accept`, body);
}

/** Say no to a colleague's request — POST /api/v1/self/roster/swaps/{swap_id}/decline (who may call: holders of self.roster.swap). */
export function declineSwap(swap_id: number, body: SwapNoteIn): Promise<DutySwapOut> {
  return api<DutySwapOut>("POST", `/self/roster/swaps/${swap_id}/decline`, body);
}

/** Withdraw my swap request (before approval) — POST /api/v1/self/roster/swaps/{swap_id}/cancel (who may call: holders of self.roster.swap). */
export function cancelSwap(swap_id: number): Promise<DutySwapOut> {
  return api<DutySwapOut>("POST", `/self/roster/swaps/${swap_id}/cancel`, undefined);
}

/** "Report Issue" (staff with ops.workorder.report) — POST /api/v1/ops/work-orders (who may call: holders of ops.workorder.report). */
export function reportOpsWorkOrders(body: IssueIn): Promise<WorkOrderOut> {
  return api<WorkOrderOut>("POST", `/ops/work-orders`, body, { idempotent: true });
}
